(function () {
    "use strict";

    function getHostDoc() {
        try {
            if (window.parent && window.parent.document && window.parent.document !== document) {
                return window.parent.document;
            }
        } catch (e) {}
        return document;
    }

    function renderOnboardingModal() {
        const doc = getHostDoc();
        if (doc.getElementById("sl-editorial-modal-root")) return;

        const overlay = doc.createElement("div");
        overlay.id = "sl-editorial-modal-root";
        overlay.className = "sl-root";
        overlay.innerHTML = `
            <style>
                .sl-root {
                    --sl-white-glass: rgba(255, 255, 255, 0.08);
                    --sl-white-border: rgba(255, 255, 255, 0.22);
                    --sl-white-border-strong: rgba(255, 255, 255, 0.45);
                    --sl-text-main: #ffffff;
                    --sl-text-dim: rgba(255, 255, 255, 0.72);
                    --sl-text-faint: rgba(255, 255, 255, 0.45);
                    --sl-display: "Didot", "Bodoni MT", "Cinzel", "Georgia", "Songti SC", "STSong", serif;

                    position: fixed;
                    inset: 0;
                    z-index: 2147483640;
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    padding: 16px;
                    box-sizing: border-box;
                    background: rgba(4, 7, 10, 0.65);
                    backdrop-filter: blur(25px) saturate(160%);
                    -webkit-backdrop-filter: blur(25px) saturate(160%);
                    color: var(--sl-text-main);
                    font-family: system-ui, -apple-system, "Segoe UI", "PingFang SC", sans-serif;
                    font-size: 13.5px;
                    line-height: 1.65;
                    -webkit-font-smoothing: antialiased;
                    -webkit-text-size-adjust: 100%;
                    text-size-adjust: 100%;
                    user-select: none;
                    animation: slFadeIn 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards;
                }

                @supports (height: 100dvh) {
                    .sl-root { bottom: auto; height: 100dvh; }
                }

                .sl-modal {
                    position: relative;
                    display: flex;
                    flex-direction: column;
                    width: 100%;
                    max-width: 540px;
                    max-height: 88vh;
                    border: 1px solid var(--sl-white-border);
                    border-radius: 16px;
                    background: var(--sl-white-glass);
                    box-shadow: 0 24px 70px rgba(0, 0, 0, 0.35), inset 0 1px 1px rgba(255, 255, 255, 0.3);
                    overflow: hidden;
                    box-sizing: border-box;
                }

                .sl-header {
                    position: relative;
                    display: flex;
                    flex-direction: column;
                    align-items: center;
                    text-align: center;
                    padding: 20px 22px 14px;
                    border-bottom: 1px solid var(--sl-white-border);
                    background: linear-gradient(180deg, rgba(255, 255, 255, 0.05) 0%, transparent 100%);
                    flex: 0 0 auto;
                }

                .sl-header-sub {
                    font-size: 9px;
                    letter-spacing: 2.5px;
                    color: var(--sl-text-faint);
                    text-transform: uppercase;
                }

                .sl-header-title {
                    margin: 4px 0 2px;
                    font-family: var(--sl-display);
                    font-size: 24px;
                    font-weight: 400;
                    letter-spacing: 3px;
                    color: var(--sl-text-main);
                    text-shadow: 0 0 20px rgba(255, 255, 255, 0.25);
                }

                .sl-header-author {
                    font-size: 10px;
                    letter-spacing: 1.5px;
                    color: var(--sl-text-dim);
                    text-transform: uppercase;
                }

                .sl-body {
                    flex: 1 1 auto;
                    min-height: 280px;
                    overflow-y: auto;
                    overscroll-behavior: contain;
                    -webkit-overflow-scrolling: touch;
                    padding: 18px 22px;
                    display: flex;
                    flex-direction: column;
                    gap: 16px;
                    box-sizing: border-box;
                }

                .sl-page {
                    display: none;
                    flex-direction: column;
                    gap: 16px;
                    animation: slPageIn 0.3s cubic-bezier(0.16, 1, 0.3, 1);
                }

                .sl-page.active {
                    display: flex;
                }

                .sl-section {
                    display: flex;
                    flex-direction: column;
                    gap: 5px;
                }

                .sl-section-title {
                    display: flex;
                    align-items: center;
                    gap: 8px;
                    font-size: 10px;
                    font-weight: 700;
                    letter-spacing: 1.8px;
                    text-transform: uppercase;
                    color: var(--sl-text-dim);
                    border-bottom: 1px solid var(--sl-white-border);
                    padding-bottom: 4px;
                }

                .sl-roman {
                    font-family: var(--sl-display);
                    font-size: 11px;
                    color: var(--sl-text-main);
                }

                .sl-text {
                    font-size: 12.5px;
                    line-height: 1.85;
                    color: var(--sl-text-dim);
                    text-align: justify;
                }

                .sl-text b {
                    color: var(--sl-text-main);
                    font-weight: 600;
                }

                .sl-list {
                    margin: 0;
                    padding-left: 15px;
                    list-style-type: square;
                    display: flex;
                    flex-direction: column;
                    gap: 3px;
                }

                .sl-code {
                    font-family: ui-monospace, "SF Mono", Menlo, monospace;
                    font-size: 11px;
                    background: rgba(255, 255, 255, 0.12);
                    padding: 1px 5px;
                    border-radius: 3px;
                    border: 1px solid var(--sl-white-border);
                    color: #fff;
                }

                .sl-link {
                    display: inline-block;
                    color: #79c0ff;
                    background: rgba(56, 139, 253, 0.15);
                    border: 1px solid rgba(56, 139, 253, 0.4);
                    padding: 1px 7px;
                    border-radius: 4px;
                    text-decoration: none;
                    font-size: 11px;
                    font-family: ui-monospace, "SF Mono", Menlo, monospace;
                    word-break: break-all;
                    vertical-align: middle;
                    transition: all 0.2s ease;
                }

                .sl-link:hover {
                    background: rgba(56, 139, 253, 0.3);
                    border-color: rgba(121, 192, 255, 0.7);
                    color: #bce1ff;
                    text-shadow: 0 0 8px rgba(121, 192, 255, 0.5);
                }

                .sl-credits-grid {
                    display: grid;
                    grid-template-columns: 1fr 1fr;
                    gap: 8px 12px;
                    margin-top: 4px;
                }

                .sl-credit-item {
                    background: rgba(255, 255, 255, 0.03);
                    border-left: 1.5px solid var(--sl-white-border-strong);
                    padding: 4px 8px;
                    display: flex;
                    flex-direction: column;
                    gap: 1px;
                }

                .sl-credit-role {
                    font-size: 9px;
                    color: var(--sl-text-faint);
                    letter-spacing: 0.5px;
                }

                .sl-credit-name {
                    font-size: 11.5px;
                    font-weight: 500;
                    color: var(--sl-text-main);
                }

                .sl-footer {
                    padding: 12px 22px 16px;
                    border-top: 1px solid var(--sl-white-border);
                    background: linear-gradient(0deg, rgba(255, 255, 255, 0.04) 0%, transparent 100%);
                    flex: 0 0 auto;
                    display: flex;
                    align-items: center;
                    justify-content: space-between;
                    gap: 10px;
                }

                .sl-page-indicator {
                    font-family: var(--sl-display);
                    font-size: 11px;
                    letter-spacing: 2px;
                    color: var(--sl-text-faint);
                }

                .sl-footer-actions {
                    display: flex;
                    align-items: center;
                    gap: 8px;
                }

                .sl-sub-btn {
                    padding: 7px 14px;
                    background: rgba(255, 255, 255, 0.08);
                    border: 1px solid var(--sl-white-border);
                    border-radius: 8px;
                    color: var(--sl-text-main);
                    font-size: 11.5px;
                    letter-spacing: 1px;
                    cursor: pointer;
                    transition: all 0.2s ease;
                }

                .sl-sub-btn:hover {
                    background: rgba(255, 255, 255, 0.16);
                }

                .sl-btn {
                    padding: 8px 18px;
                    background: rgba(255, 255, 255, 0.92);
                    border: 1px solid #ffffff;
                    border-radius: 8px;
                    color: #0c1015;
                    font-family: system-ui, -apple-system, sans-serif;
                    font-size: 12.5px;
                    font-weight: 600;
                    letter-spacing: 1.5px;
                    text-transform: uppercase;
                    cursor: pointer;
                    box-shadow: 0 4px 20px rgba(0, 0, 0, 0.2);
                    transition: all 0.2s ease;
                }

                .sl-btn:hover {
                    background: #ffffff;
                    transform: translateY(-1px);
                    box-shadow: 0 6px 24px rgba(255, 255, 255, 0.3);
                }

                .sl-body::-webkit-scrollbar { width: 3px; }
                .sl-body::-webkit-scrollbar-thumb {
                    background: rgba(255, 255, 255, 0.2);
                    border-radius: 2px;
                }

                @keyframes slFadeIn {
                    from { opacity: 0; transform: scale(0.96); }
                    to { opacity: 1; transform: scale(1); }
                }

                @keyframes slPageIn {
                    from { opacity: 0; transform: translateX(8px); }
                    to { opacity: 1; transform: translateX(0); }
                }

                @media (max-width: 560px) {
                    .sl-root { padding: 0; background: rgba(4, 7, 10, 0.85); }
                    .sl-modal { max-width: none; height: 100%; max-height: 100%; border: none; border-radius: 0; background: rgba(255, 255, 255, 0.05); }
                    .sl-header, .sl-body, .sl-footer { padding-left: 16px; padding-right: 16px; }
                    .sl-header-title { font-size: 20px; }
                    .sl-footer { padding-bottom: calc(14px + env(safe-area-inset-bottom, 0px)); }
                    .sl-credits-grid { grid-template-columns: 1fr; }
                }
            </style>

            <div class="sl-modal">
                <div class="sl-header">
                    <div class="sl-header-sub" id="sl-header-edition">SPECIAL EDITION · VOL. 5.3</div>
                    <div class="sl-header-title">SL 5.3</div>
                    <div class="sl-header-author">@NUE · 喵喵电波</div>
                </div>

                <div class="sl-body">
                    <!-- 第 1 页：使用须知 -->
                    <div class="sl-page active" id="sl-page-1">
                        <div class="sl-section">
                            <div class="sl-section-title">
                                <span class="sl-roman">I.</span>
                                <span>协议与声明</span>
                            </div>
                            <div class="sl-text">
                                禁二传、仅发布于 MoM，二改请参考 MOM 授权。本人严格遵守法律法规和社会主义核心价值观。如有恶意篡改和使用出现违法事项，本人概不承担任何法律责任。<b>使用本预设即代表同意此声明，一切非法使用后果皆由使用者承担。</b>
                            </div>
                        </div>

                        <div class="sl-section">
                            <div class="sl-section-title">
                                <span class="sl-roman">II.</span>
                                <span>基础功能</span>
                            </div>
                            <ul class="sl-list sl-text">
                                <li><b>修改字数与段落</b>：请在 <span class="sl-code">📌✧SETTING</span> 中调整。</li>
                                <li><b>大总结</b>：通过下方快速回复栏发送 <b>QR 大总结</b> 触发。</li>
                                <li><b>注意1</b>：本预设<b>未预设独立文风选项</b>。</li>
                                <li><b>注意2</b>：build端/build端的抗截断模型中<b>，若存在爆思维链问题，请关闭“返回思维链”，0913build暗改了flash模型的提示词，导致现在提示词版本有点失效，v端无影响</b>。</li>
                            </ul>
                        </div>

                        <div class="sl-section">
                            <div class="sl-section-title">
                                <span class="sl-roman">III.</span>
                                <span>选开指引</span>
                            </div>
                            <ul class="sl-list sl-text">
                                <li><b>🟡</b>：选一开（单选）。</li>
                                <li><b>🔎</b>：可多选。</li>                     
                                <li><b>[自定义]</b>：预留的缝合与扩展位置。</li>
                            </ul>
                        </div>

                        <div class="sl-section">
                            <div class="sl-section-title">
                                <span class="sl-roman">IV.</span>
                                <span>注意事项</span>
                            </div>
                            <ul class="sl-list sl-text">
                                <li>SL 是一款默认以<b>自主 RP（角色扮演）</b>为主要功能的预设。</li>
                                <li>严禁在倒卖群、贩子群及非 ST 环境中使用。</li>
                                <li>文中未提及的条目<b>请勿随意关闭</b>；必须外挂预设世界书与实验性宏搭配使用，确保酒馆版本为 <b>1.7 / 1.8</b>及其以上。</li>
                                <li>本页面会在每次打开脚本的时候出现。</li>
                            </ul>
                        </div>

                        <div class="sl-section">
                            <div class="sl-section-title">
                                <span class="sl-roman">V.</span>
                                <span>致谢</span>
                            </div>
                            <div class="sl-credits-grid">
                                <div class="sl-credit-item">
                                    <span class="sl-credit-role">[去标签] NPC Profile</span>
                                    <span class="sl-credit-name">@colerith</span>
                                </div>
                                <div class="sl-credit-item">
                                    <span class="sl-credit-role">[小剧场] Theater</span>
                                    <span class="sl-credit-name">@hui_chan</span>
                                </div>

<div class="sl-credit-item">
                                    <span class="sl-credit-role">F尾部部分破限词</span>
                                    <span class="sl-credit-name">@shenshu0_0</span>
                                </div>
                                <div class="sl-credit-item">
                                    <span class="sl-credit-role">脚本代码参考</span>
                                    <span class="sl-credit-name">@colerith</span>
                                </div>
                                <div class="sl-credit-item">
                                    <span class="sl-credit-role">GLM尾部</span>
                                    <span class="sl-credit-name">@shenshu0_0</span>
                                </div>
                                <div class="sl-credit-item">
                                    <span class="sl-credit-role">Flash 系列尾部</span>
                                    <span class="sl-credit-name">@menchine_</span>
                                </div>
                            </div>
                        </div>
                    </div>

                    <!-- 第 2 页：更新日志 -->
                    <div class="sl-page" id="sl-page-2">
                        <div class="sl-section">
                            <div class="sl-section-title">
                                <span class="sl-roman">✦</span>
                                <span>5.1 ➔ 5.3 更新</span>
                            </div>
                            <div class="sl-text">
                                5.3 围绕小剧场体验、独立番外和世界书兼容进行了更新。
                            </div>
                            <ul class="sl-list sl-text">
                                <li><b>小剧场</b>：调整为短句对白式演出，突出轻松趣味、节奏感和 NPC 个性；保留随机主题宏。</li>
                                <li><b>独立番外</b>：新增绿灯触发提示，强化趣味写作与 HTML/CSS 排版指导，适配手机、平板和桌面。</li>
                                <li><b>世界书</b>：新增番外提示条目和预设锚点；加载预设时可将缺失条目合并进旧世界书并全局挂载。</li>
                            </ul>
                        </div>
                        <div class="sl-section">
                            <div class="sl-section-title">
