            return Object.keys(expected).every(key =>
                Object.prototype.hasOwnProperty.call(actual, key) &&
                matchesExpectedValue(actual[key], expected[key])
            );
        }
        return actual === expected;
    }

    function worldbookMatches(current, expected) {
        return Array.isArray(current) && current.length === expected.length &&
            expected.every((entry, index) => matchesExpectedValue(current[index], entry));
    }

