    // refresh the Theater prompt, and add only missing default entries.
    function mergeWorldbook(current, defaults) {
        const merged = current.map(entry => ({ ...entry }));

        for (const defaultEntry of defaults) {
            let index = merged.findIndex(entry =>
                entry.uid === defaultEntry.uid && entry.name === defaultEntry.name
            );

            if (index < 0 && defaultEntry.outletName) {
                index = merged.findIndex(entry =>
                    entry.uid === defaultEntry.uid && entry.outletName === defaultEntry.outletName
                );
            }

            if (index < 0) {
                index = merged.findIndex(entry => entry.name === defaultEntry.name);
            }

            if (index < 0) {
                const addition = { ...defaultEntry };
                if (merged.some(entry => entry.uid === addition.uid)) {
                    const usedUids = new Set(merged.map(entry => entry.uid));
                    let availableUid = 0;
                    while (usedUids.has(availableUid)) availableUid++;
                    addition.uid = availableUid;
                }
                merged.push(addition);
                continue;
            }

            // Existing Theater entries receive the new prompt while retaining
            // their activation rules, outlet settings, and other user changes.
            if (defaultEntry.name === "Theater" || defaultEntry.outletName === "theater" || defaultEntry.name === "Theater Prompt Enhancement" || defaultEntry.outletName === "theater_prompt_enhancement") {
                merged[index] = {
                    ...merged[index],
                    content: defaultEntry.content
                };
            }
        }

        return merged;
    }

