        detail = notice.conflicts ? `保留了 ${notice.conflicts} 处本地修改。` : '更新前备份已保存，可下载或恢复。';
        win.toastr?.success?.(status);
    }
} catch { /* A notice must not prevent initialization. */ }
render();

})().catch(error => console.error("[SL 更新]", error));
